import{E as e,F as t,q as n,w as r}from"./vue.runtime.esm-bundler-DZZTqpJU.js";t();var i={class:`markdown-body`},a={__name:`jq.zh`,setup(t,{expose:a}){return a({frontmatter:{}}),(t,a)=>(n(),r(`div`,i,[...a[0]||=[e(`<h1>使用 jq 处理 JSON</h1><p>jq 是一款实用的工具，用于对结构化 JSON 数据进行切片、过滤、映射和转换。</p><h2>安装 jq</h2><h3>在 Mac OS 上</h3><p><code>brew install jq</code></p><h3>在 AWS Linux 上</h3><p>当前 AMI 上无法通过 yum 安装，但最新的 AMI 应该支持：<a href="https://aws.amazon.com/amazon-linux-ami/2015.09-release-notes/">https://aws.amazon.com/amazon-linux-ami/2015.09-release-notes/</a></p><p>从源码安装较为复杂。</p><h2>实用参数</h2><p>运行 jq 时，以下参数可能很有用：</p><table><thead><tr><th>参数</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td><code>--version</code></td><td style="text-align:left;">输出版本号并以零状态退出。</td></tr><tr><td><code>--sort-keys</code></td><td style="text-align:left;">按排序后的键顺序输出每个对象的字段。</td></tr></tbody></table><h2>基本概念</h2><p>jq 的语法非常一致：</p><table><thead><tr><th>语法</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td>,</td><td style="text-align:left;">以逗号分隔的过滤器会产生多个独立的输出</td></tr><tr><td>?</td><td style="text-align:left;">当类型不符合预期时将忽略错误</td></tr><tr><td>[]</td><td style="text-align:left;">数组构造</td></tr><tr><td>{}</td><td style="text-align:left;">对象构造</td></tr><tr><td>+</td><td style="text-align:left;">拼接或加法</td></tr><tr><td>-</td><td style="text-align:left;">集合差集或减法</td></tr><tr><td>length</td><td style="text-align:left;">选中元素的大小</td></tr><tr><td>|</td><td style="text-align:left;">管道符，用于以类似 bash 的方式串联命令</td></tr></tbody></table><h2>处理 JSON 对象</h2><table><thead><tr><th>描述</th><th style="text-align:left;">命令</th></tr></thead><tbody><tr><td>显示所有键</td><td style="text-align:left;"><code>jq &#39;keys&#39;</code></td></tr><tr><td>对所有元素加 1</td><td style="text-align:left;"><code>jq &#39;map_values(.+1)&#39;</code></td></tr><tr><td>删除一个键</td><td style="text-align:left;"><code>jq &#39;del(.foo)&#39;</code></td></tr><tr><td>将对象转换为数组</td><td style="text-align:left;"><code>to_entries &amp;#124; map([.key, .value])</code></td></tr></tbody></table><h2>处理字段</h2><table><thead><tr><th>描述</th><th style="text-align:left;">命令</th></tr></thead><tbody><tr><td>拼接两个字段</td><td style="text-align:left;"><code>fieldNew=.field1+&#39; &#39;+.field2</code></td></tr></tbody></table><h2>处理 JSON 数组</h2><h3>切片与过滤</h3><table><thead><tr><th>描述</th><th style="text-align:left;">命令</th></tr></thead><tbody><tr><td>全部</td><td style="text-align:left;"><code>jq .[]</code></td></tr><tr><td>第一个</td><td style="text-align:left;"><code>jq &#39;.[0]&#39;</code></td></tr><tr><td>范围</td><td style="text-align:left;"><code>jq &#39;.[2:4]&#39;</code></td></tr><tr><td>前 3 个</td><td style="text-align:left;"><code>jq &#39;.[:3]&#39;</code></td></tr><tr><td>后 2 个</td><td style="text-align:left;"><code>jq &#39;.[-2:]&#39;</code></td></tr><tr><td>倒数第二个</td><td style="text-align:left;"><code>jq &#39;.[-2]&#39;</code></td></tr><tr><td>按值筛选整数数组</td><td style="text-align:left;"><code>jq &#39;map(select(. &gt;= 2))&#39;</code></td></tr><tr><td>按值筛选对象数组</td><td style="text-align:left;"><code>jq &#39;.[] &amp;#124; select(.id == &quot;second&quot;)&#39;</code></td></tr><tr><td>按类型筛选</td><td style="text-align:left;"><code>jq &#39;.[] &amp;#124; numbers&#39;</code> 类型包括 arrays, objects, iterables, booleans, numbers, normals, finites, strings, nulls, values, scalars</td></tr></tbody></table><h3>映射与转换</h3><table><thead><tr><th>描述</th><th style="text-align:left;">命令</th></tr></thead><tbody><tr><td>对所有元素加 1</td><td style="text-align:left;"><code>jq &#39;map(.+1)&#39;</code></td></tr><tr><td>删除 2 个元素</td><td style="text-align:left;"><code>jq &#39;del(.[1, 2])&#39;</code></td></tr><tr><td>拼接数组</td><td style="text-align:left;"><code>jq &#39;add&#39;</code></td></tr><tr><td>展平数组</td><td style="text-align:left;"><code>jq &#39;flatten&#39;</code></td></tr><tr><td>创建数字范围</td><td style="text-align:left;"><code>jq &#39;[range(2;4)]&#39;</code></td></tr><tr><td>显示每个元素的类型</td><td style="text-align:left;"><code>jq &#39;map(type)&#39;</code></td></tr><tr><td>对基本类型数组排序</td><td style="text-align:left;"><code>jq &#39;sort&#39;</code></td></tr><tr><td>对对象数组排序</td><td style="text-align:left;"><code>jq &#39;sort_by(.foo)&#39;</code></td></tr><tr><td>按键分组 - 与展平相反</td><td style="text-align:left;"><code>jq &#39;group_by(.foo)&#39;</code></td></tr><tr><td>数组的最小值</td><td style="text-align:left;"><code>jq &#39;min&#39;</code> 。另请参阅 min, max, min_by(path_exp), max_by(path_exp)</td></tr><tr><td>去除重复项</td><td style="text-align:left;"><code>jq &#39;unique&#39;</code> 或 <code>jq &#39;unique_by(.foo)&#39;</code> 或 <code>jq &#39;unique_by(length)&#39;</code></td></tr><tr><td>反转数组</td><td style="text-align:left;"><code>jq &#39;reverse&#39;</code></td></tr></tbody></table>`,23)]]))}};export{a as default};